# Algorithms
def bsearch(a, t):
    lo = 0
    hi = len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == t:
            return mid
        if a[mid] < t:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
def sieve(n):
    flags = [True] * (n + 1)
    flags[0] = False
    flags[1] = False
    i = 2
    while i * i <= n:
        if flags[i]:
            j = i * i
            while j <= n:
                flags[j] = False
                j = j + i
        i = i + 1
    out = []
    for i in range(2, n + 1):
        if flags[i]:
            out.append(i)
    return out
a = [1, 3, 5, 7, 9, 11]
print(bsearch(a, 7), bsearch(a, 4))
print(sieve(30))
